// Comptabilite, RapportAnnuel, Presences, PresentationAssociation,
// PublicShowcase, GestionAcces) restent visuellement cohérents avec
// App.jsx — TEAL sert ici de vert « succès » sémantique, distinct de la
// couleur de marque (--primary/--accent, pilotée par association.couleur_*).
export const TEAL = "#1F8A5C";
export const TEAL_LIGHT = "#E4F2EE";
export const RED = "#C0392B";
export const CHARCOAL = "#182233";
export const BG = "#FBF6EC";
export const GOLD_LIGHT = "#E8CE7A";

// Formate un montant selon la devise de l'association (2026-09-27,
// chantier « internationalisation » — voir internationalisation-universelle.md).
// Utilise Intl.NumberFormat plutôt qu'un simple suffixe : chaque devise a
// ses propres règles d'affichage (ex. le Franc CFA — XAF/XOF — ne s'affiche
// jamais avec des centimes, contrairement au dollar canadien), et
// Intl.NumberFormat les connaît nativement pour n'importe quel code ISO
// 4217, sans configuration à maintenir. currencyDisplay: "code" conserve le
// même style visuel qu'avant (le code à la suite du montant, ex. "25,00
// CAD") plutôt qu'un symbole qui varie d'une devise à l'autre. Si le code
// saisi par l'association n'est pas un code ISO valide, on retombe sur
// l'ancien affichage plutôt que de faire planter l'application.
export function money(n, devise = "CAD") {
  const v = Number(n) || 0;
  const code = (devise || "CAD").trim().toUpperCase();
  try {
    return new Intl.NumberFormat("fr-CA", { style: "currency", currency: code, currencyDisplay: "code" }).format(v);
  } catch {
    const sign = v < 0 ? "-" : "";
    return `${sign}${Math.abs(v).toLocaleString("fr-CA", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${code}`;
  }
}

// Dates et heures saisies dans un <input type="datetime-local"> (correctif
// fuseau horaire, 2026-10-08 — déplacé depuis Presences.jsx pour que tous
// les écrans l'utilisent). Ce champ donne une heure SANS fuseau (ex.
// "2026-10-10T18:00"). Envoyée telle quelle, Postgres la lisait comme de
// l'UTC : un événement saisi à 18 h à Halifax (UTC−3) s'affichait à 15 h.
// datetimeLocalToISO l'interprète dans le fuseau de l'appareil qui saisit,
// puis la convertit en UTC pour le stockage timestamptz.
export function datetimeLocalToISO(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}
// Sens inverse, pour pré-remplir un formulaire de modification : heure
// LOCALE de l'appareil, chiffre par chiffre. Un simple iso.slice(0, 16)
// afficherait l'heure UTC brute, décalée hors UTC.
export function toDatetimeLocal(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}
// Date et heure lisibles d'un événement, ex. « samedi 10 octobre 2026 à
// 18 h 00 » / « Saturday, October 10, 2026 at 6:00 p.m. ».
export function formatEventDateTime(iso, lang) {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  const locale = lang === "en" ? "en-CA" : "fr-CA";
  const jour = d.toLocaleDateString(locale, { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  const heure = d.toLocaleTimeString(locale, { hour: "numeric", minute: "2-digit" });
  return lang === "en" ? `${jour} at ${heure}` : `${jour} à ${heure}`;
}

// Montant « en toutes lettres » (français) — mention obligatoire du reçu
// fiscal CERFA 2041-RD (reçu fiscal conforme, 2026-10-06). Le nom de la
// devise elle-même (« euros », « dollars canadiens »...) n'est PAS une
// liste codée à la main : on la lit directement d'Intl.NumberFormat avec
// currencyDisplay: "name" (même esprit que currencyOptions ci-dessous) —
// le navigateur sait déjà, pour n'importe quel code ISO 4217 et n'importe
// quel montant, s'il faut écrire « un euro » ou « deux euros » (règles de
// pluriel). Seule la partie numérique (zéro à 999 999 999) est convertie
// nous-mêmes, selon l'orthographe française courante (rectifiée 1990 :
// "quatre-vingt-un", pas d'espace autour des tirets composés).
const FR_UNITS = ["zéro", "un", "deux", "trois", "quatre", "cinq", "six", "sept", "huit", "neuf", "dix", "onze", "douze", "treize", "quatorze", "quinze", "seize", "dix-sept", "dix-huit", "dix-neuf"];
const FR_TENS = ["", "", "vingt", "trente", "quarante", "cinquante", "soixante", "soixante-dix", "quatre-vingt", "quatre-vingt-dix"];
function frTwoDigits(num) {
  if (num < 20) return FR_UNITS[num];
  const dizaine = Math.floor(num / 10);
  const unite = num % 10;
  if (dizaine === 7 || dizaine === 9) {
    const base = dizaine === 7 ? "soixante" : "quatre-vingt";
    if (unite === 1 && dizaine === 7) return base + "-et-onze";
    return base + "-" + FR_UNITS[10 + unite];
  }
  if (dizaine === 8) return unite === 0 ? "quatre-vingts" : "quatre-vingt-" + FR_UNITS[unite];
  const base = FR_TENS[dizaine];
  if (unite === 0) return base;
  if (unite === 1) return base + "-et-un";
  return base + "-" + FR_UNITS[unite];
}
function frThreeDigits(num) {
  const centaines = Math.floor(num / 100);
  const reste = num % 100;
  let words = "";
  if (centaines > 0) {
    words = centaines === 1 ? "cent" : FR_UNITS[centaines] + " cent";
    if (reste === 0 && centaines > 1) words += "s";
  }
  if (reste > 0) words = words ? words + " " + frTwoDigits(reste) : frTwoDigits(reste);
  return words;
}
function nombreEnLettresFr(n) {
  const entier = Math.floor(Math.abs(Number(n) || 0));
  if (entier === 0) return "zéro";
  const groupes = [];
  let reste = entier;
  while (reste > 0) { groupes.unshift(reste % 1000); reste = Math.floor(reste / 1000); }
  const nb = groupes.length;
  const parts = [];
  groupes.forEach((valeur, i) => {
    if (valeur === 0) return;
    const echelle = nb - 1 - i; // 0=unités, 1=mille, 2=million, 3=milliard
    if (echelle === 1) parts.push(valeur === 1 ? "mille" : frThreeDigits(valeur) + " mille");
    else if (echelle >= 2) parts.push(frThreeDigits(valeur) + " " + (echelle === 2 ? "million" : "milliard") + (valeur > 1 ? "s" : ""));
    else parts.push(frThreeDigits(valeur));
  });
  return parts.join(" ");
}
// Nom de la devise (singulier/pluriel déjà corrects), lu depuis Intl plutôt
// qu'une table à maintenir à la main.
function deviseEnMotsFr(montant, code) {
  try {
    const parts = new Intl.NumberFormat("fr-FR", { style: "currency", currency: (code || "EUR").toUpperCase(), currencyDisplay: "name" }).formatToParts(Math.abs(montant) || 0);
    const part = parts.find((p) => p.type === "currency");
    return part ? part.value : code;
  } catch { return code || ""; }
}
export function montantEnLettres(montant, devise) {
  const v = Number(montant) || 0;
  const entier = Math.floor(v);
  const centimes = Math.round((v - entier) * 100);
  let mots = nombreEnLettresFr(entier);
  mots = mots.charAt(0).toUpperCase() + mots.slice(1);
  let resultat = `${mots} ${deviseEnMotsFr(entier, devise)}`;
  if (centimes > 0) {
    resultat += ` et ${nombreEnLettresFr(centimes)} centime${centimes > 1 ? "s" : ""}`;
  }
  return resultat;
}

