// Reçu officiel de don conforme Canada (règles de l'ARC/CRA), 2026-10-06 —
// deuxième juridiction du même chantier, après la France ci-dessus.
// Implémente la règle du « reçu fractionné » (split receipting) : quand le
// donateur reçoit un avantage en contrepartie du don (ex. repas d'un
// événement-bénéfice), le montant admissible aux fins de l'impôt n'est
// pas simplement le montant du don — voir les trois cas gérés ci-dessous,
// chacun sourcé sur canada.ca/charities-giving (page "Split receipting").
//
// 1. Règle des 80 % : si la juste valeur marchande (JVM) de l'avantage
//    dépasse 80 % de la JVM du don, l'ARC présume qu'il n'y a aucune
//    intention véritable de faire un don — AUCUN reçu ne peut être émis
//    (sauf preuve contraire, que l'application ne peut pas évaluer :
//    reste une décision humaine, cette fonction se contente de signaler
//    le cas plutôt que de l'autoriser silencieusement).
// 2. Seuil de minimis : un avantage dont la JVM est inférieure au plus
//    petit de 75 $ ou de 10 % de la JVM du don n'a PAS besoin d'être
//    soustrait — sauf s'il s'agit d'une quasi-espèce (carte-cadeau) ou
//    d'un élément d'événement-bénéfice (repas, droits de green), qui doit
//    TOUJOURS être soustrait (`avantageTypeExclu`).
// 3. Sinon : montant admissible = montant du don − JVM de l'avantage.
export function calculerMontantAdmissibleCanada({ montant, valeurAvantage, avantageTypeExclu }) {
  const m = Number(montant) || 0;
  const a = Number(valeurAvantage) || 0;
  if (a <= 0) return { admissible: m, aSoustraire: 0, recuPossible: true, regle80Depassee: false };
  if (a > 0.8 * m) return { admissible: 0, aSoustraire: a, recuPossible: false, regle80Depassee: true };
  const seuilMinimis = Math.min(75, 0.1 * m);
  if (!avantageTypeExclu && a < seuilMinimis) return { admissible: m, aSoustraire: 0, recuPossible: true, regle80Depassee: false };
  return { admissible: Math.max(0, m - a), aSoustraire: a, recuPossible: true, regle80Depassee: false };
}
export const RECU_CA_FMV_SEUIL_EVALUATEUR = 1000;

// Liste complète des devises ISO 4217 reconnues par le navigateur
// (Intl.supportedValuesOf), avec un nom lisible dans la langue de
// l'interface (Intl.DisplayNames) — ex. { code: "XAF", label: "XAF —
// franc CFA (BEAC)" }. Aucune liste à maintenir à la main : couvre
// automatiquement toute nouvelle devise que le navigateur reconnaît.
// Repli sur une courte liste si le navigateur ne supporte pas ces API
// (très ancien navigateur) plutôt que de laisser le sélecteur vide.
const FALLBACK_CURRENCIES = ["CAD", "USD", "EUR", "XAF", "XOF", "GBP", "CHF", "MAD", "CNY", "INR"];
export function currencyOptions(lang) {
  let codes;
  try {
    codes = typeof Intl.supportedValuesOf === "function" ? Intl.supportedValuesOf("currency") : FALLBACK_CURRENCIES;
  } catch {
    codes = FALLBACK_CURRENCIES;
  }
  let names = null;
  try {
    names = new Intl.DisplayNames([lang === "en" ? "en" : "fr"], { type: "currency" });
  } catch {
    names = null;
  }
  return codes
    .map((code) => {
      let name;
      try { name = names ? names.of(code) : null; } catch { name = null; }
      return { code, label: name ? `${code} — ${name}` : code };
    })
    .sort((a, b) => a.code.localeCompare(b.code));
}

// Liste des fuseaux horaires IANA reconnus par le navigateur
// (Intl.supportedValuesOf("timeZone"), 2026-09-27 — chantier « fuseau
// horaire », voir internationalisation-universelle.md). Sert à choisir
// l'heure locale de l'association : c'est ce fuseau qui détermine à quelle
// heure locale ses rappels automatiques par courriel sont envoyés (voir
// sql/2026-09-27b_fuseau_horaire.sql). Chaque option affiche le décalage
// UTC actuel (ex. "America/Moncton (UTC-03:00)") pour aider à choisir sans
// avoir à connaître le nom exact. Intl.DisplayNames ne couvre pas les
// fuseaux horaires (seulement langue/région/devise/etc.), donc on calcule
// le décalage nous-mêmes via Intl.DateTimeFormat plutôt que d'afficher un
// nom traduit. Repli sur une courte liste si le navigateur ne supporte pas
// ces API.
const FALLBACK_TIMEZONES = [
  "America/Moncton", "America/Toronto", "America/Montreal", "America/Vancouver",
  "America/New_York", "America/Los_Angeles", "Africa/Douala", "Africa/Yaounde",
  "Africa/Abidjan", "Africa/Dakar", "Europe/Paris", "Europe/London", "Asia/Dubai",
];
export function timezoneOptions() {
  let zones;
  try {
    zones = typeof Intl.supportedValuesOf === "function" ? Intl.supportedValuesOf("timeZone") : FALLBACK_TIMEZONES;
  } catch {
    zones = FALLBACK_TIMEZONES;
  }
  const now = new Date();
  return zones
    .map((tz) => {
      let offsetLabel = "UTC+00:00";
      let offsetMinutes = 0;
      try {
        const parts = new Intl.DateTimeFormat("en-US", { timeZone: tz, timeZoneName: "longOffset" }).formatToParts(now);
        const part = parts.find((p) => p.type === "timeZoneName");
        const raw = part ? part.value : "GMT+00:00"; // ex. "GMT-03:00"
        offsetLabel = raw.replace("GMT", "UTC");
        const m = raw.match(/GMT([+-])(\d{2}):(\d{2})/);
        if (m) offsetMinutes = (m[1] === "-" ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3]));
      } catch {
        // navigateur très ancien ou fuseau inconnu : garde le repli UTC+00:00.
      }
      return { tz, label: `${tz.replace(/_/g, " ")} (${offsetLabel})`, offsetMinutes };
    })
    .sort((a, b) => a.offsetMinutes - b.offsetMinutes || a.tz.localeCompare(b.tz));
}
export function uid() { return Math.random().toString(36).slice(2, 10); }
export function todayISO() { return new Date().toISOString().slice(0, 10); }

// Normalisation de texte pour la recherche globale (Phase 6, feuille de
// route, 2026-09-29) — insensible aux accents et à la casse, pour qu'une
// recherche "ecole" trouve aussi "École". Même principe que le slugify()
// de RapportAnnuel.jsx, mais sans retirer les espaces/ponctuation : ici on
// veut comparer des morceaux de phrase (ex. "assemblée generale" doit
// matcher "Assemblée Générale"), pas produire un identifiant.
export function foldText(s) {
  return (s ?? "").toString().normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();
}

// Bornes [début, fin] (ISO) de l'exercice financier qui commence en
// `anneeRef` avec un mois de début `moisDebut` (1-12, voir
// `associations.exercice_mois_debut`, suite 86 Phase B). Formule uniforme,
// valable que l'exercice suive l'année civile (moisDebut=1) ou soit décalé.
// Extrait de Comptabilite.jsx (Phase B) pour être réutilisable ailleurs —
// notamment par RapportAnnuel.jsx (Phase C, branchement du rapport annuel
// sur le même exercice financier que le reste du système comptable).
export function exerciceBounds(anneeRef, moisDebut) {
  const debut = `${anneeRef}-${String(moisDebut).padStart(2, "0")}-01`;
  const fin = new Date(Date.UTC(anneeRef + 1, moisDebut - 1, 0)).toISOString().slice(0, 10);
  return { debut, fin };
}

// Détecte si une erreur Supabase/fetch est due à une perte de réseau (hors
// ligne, requête qui n'a jamais atteint le serveur) plutôt qu'à une vraie
// erreur applicative (contrainte, permission...). Extrait de friendlyError
// (suite 84b, 2026-09-28) pour être réutilisable ailleurs — notamment par
// AuthenticatedApp (App.jsx) qui doit distinguer ce cas précis pour retomber
// sur le profil mis en cache plutôt que d'afficher un écran d'erreur bloquant.
export function isNetworkError(error) {
  if (!error) return false;
  const msg = error.message || "";
  return !navigator?.onLine || /Failed to fetch|NetworkError|network error/i.test(msg);
}

// Traduit une erreur Supabase/Postgres/PostgREST technique en un message
// compréhensible pour un humain, plutôt que d'afficher le texte brut renvoyé
// par la base (ex. « duplicate key value violates unique constraint... »).
// Généralisé à toute l'application (2026-09-21) à partir du modèle déjà en
// place dans Funeraire.jsx (suite 70) — demande directe de l'utilisateur
// ("les messages d'erreur [doivent être] lisibles par des humains").
// Usage : friendlyError(error, t) où `t` vient de useLang(). Le détail
// technique original reste visible (console.error côté appelant, et en
// petit texte ici) pour le diagnostic, sans être ce que l'utilisateur voit
// en premier.
export function friendlyError(error, t) {
  if (!error) return t("err_generic");
  const msg = error.message || "";
  // Erreur de schéma PostgREST (ex. "Could not find the 'telephone' column
  // of 'members' in the schema cache") : signifie qu'une migration SQL
  // attendue n'a pas encore été exécutée sur la base — pas une erreur de
  // saisie de l'utilisateur, donc message dédié plutôt que le générique.
  if (error.code === "PGRST204" || error.code === "PGRST205" || /schema cache/i.test(msg)) {
    return t("err_schema_pending");
  }
  // Erreur d'authentification Supabase à la création de compte : un compte
  // existe déjà avec ce courriel. Pas une erreur générique — un cas
  // fréquent et attendu (ex. quelqu'un qui retente de créer un compte
  // alors qu'il en a déjà un, ou une deuxième association créée par erreur
  // avec le même courriel), donc message dédié et actionnable plutôt que le
  // texte technique brut ("User already registered") qui s'affichait tel
  // quel derrière "Détail technique :" (suite 2026-10-06, signalé par
  // l'utilisateur comme illisible). error.code couvre les versions
  // récentes de supabase-js (AuthApiError.code), le test sur msg couvre les
  // versions plus anciennes qui ne renvoient que le message.
  if (error.code === "user_already_exists" || error.code === "email_exists" || /user already registered|already registered/i.test(msg)) {
    return t("err_auth_user_exists");
  }
  // Erreur PostgREST quand une requête ".single()" ne trouve ni plus ni
  // moins qu'une seule ligne attendue (ex. profil, association ou
  // abonnement introuvable ou dupliqué) : le code reste PGRST116 dans
  // toutes les versions de supabase-js, mais le texte du message a changé
  // d'une version à l'autre ("JSON object requested, multiple (or no) rows
  // returned" puis "Cannot coerce the result to a single JSON object") —
  // signalé par l'utilisateur comme illisible derrière "Détail technique :"
  // (2026-10-06), même pattern que user_already_exists ci-dessus.
  if (error.code === "PGRST116" || /cannot coerce the result to a single json object|multiple \(or no\) rows returned/i.test(msg)) {
    return t("err_single_row_not_found");
  }
  if (isNetworkError(error)) {
    return t("err_network");
  }
  switch (error.code) {
    case "23505": return t("err_duplicate");
    case "23503": return t("err_foreign_key");
    case "23502": return t("err_missing_value");
    case "23514": return t("err_invalid_value");
    case "42501": return t("err_permission");
    default: return t("err_generic") + (msg ? ` ${t("err_technical_detail")} ${msg}` : "");
  }
}

// =====================================================================
// CACHE LOCAL DU PROFIL (mode hors-ligne/PWA, suite 84b, 2026-09-28)
// =====================================================================
// Corrige un écart constaté par l'utilisateur entre ce qui avait été promis
// pour la suite 84 (« la coquille de l'application reste visible hors
// ligne ») et le comportement réel observé : au démarrage, AuthenticatedApp
// (App.jsx) doit d'abord recharger le profil (rôle/nom/association) depuis
// Supabase avant d'afficher quoi que ce soit — cet appel n'est jamais mis en
// cache par le Service Worker (délibérément, pour ne jamais servir une
// donnée périmée en silence pour les VRAIES données de l'app), donc hors
// ligne il échouait et bloquait tout l'affichage (menu compris) derrière un
// écran d'erreur plein écran, au lieu de laisser voir au moins le menu.
//
// Ici, c'est différent d'un cache général : on ne mémorise QUE le dernier
// profil/association/abonnement chargés avec succès pour CE compte précis
// (clé incluant l'id utilisateur), et on ne s'en sert QUE comme repli
// explicite quand le rechargement échoue spécifiquement pour une raison
// réseau (isNetworkError) — jamais pour remplacer un vrai chargement qui
// réussit, et jamais pour une autre erreur (permission, compte bloqué...).
// La bannière hors-ligne déjà affichée (OfflineBanner) reste le signal que
// ce qui est affiché peut ne plus être à jour.
function authCacheKey(userId) { return `arem_auth_cache_${userId}`; }

export function cacheAuthSnapshot(userId, snapshot) {
  try {
    localStorage.setItem(authCacheKey(userId), JSON.stringify({ ...snapshot, cachedAt: Date.now() }));
  } catch {
    // Stockage indisponible (navigation privée pleine, quota atteint...) :
    // le repli hors ligne sera simplement indisponible, rien de plus grave.
  }
}

export function readCachedAuthSnapshot(userId) {
  try {
    const raw = localStorage.getItem(authCacheKey(userId));
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

// =====================================================================
// PRIMITIVES UI (couleurs dynamiques via variables CSS --primary/--accent,
// posées par l'application principale sur un conteneur parent)
// =====================================================================
export function Section({ children, style }) { return <section style={{ padding: "32px 0", ...style }}>{children}</section>; }
export function Container({ children, style }) { return <div style={{ maxWidth: 1180, margin: "0 auto", padding: "0 24px", ...style }}>{children}</div>; }
export function Pill({ children, color = TEAL, bg = TEAL_LIGHT }) {
  return <span style={{ display: "inline-block", background: bg, color, fontSize: 12, fontWeight: 700, letterSpacing: 0.4, textTransform: "uppercase", padding: "4px 12px", borderRadius: 999 }}>{children}</span>;
}
export function Card({ children, style }) {
  // overflowWrap (suite Phase 6, 2026-09-29) — protège TOUTES les cartes de
  // l'appli contre un texte trop long sans espace (ex. un message d'erreur
  // technique collé par erreur dans une annonce) qui, sans ça, élargit la
  // carte au-delà de l'écran et fait apparaître le fond sombre de la page
  // pendant le défilement horizontal. Voir aussi overflow-x sur <body>
  // (index.css) : double protection, ici on garde le texte lisible en le
  // faisant revenir à la ligne plutôt que de le couper.
  // minWidth: 0 (même suite, 2026-09-29) — complète overflowWrap : dans
  // une grille/flex CSS, un enfant garde par défaut une largeur minimale
  // égale à celle de son contenu NON coupé (min-width: auto), même si ce
  // contenu pourrait revenir à la ligne. C'était la vraie cause du texte
  // encore tronqué en mode portrait (mais lisible en paysage, où l'écran
  // dépassait cette largeur minimale) malgré overflowWrap : le texte
  // était prêt à revenir à la ligne, mais la carte n'avait pas le droit
  // de rétrécir pour l'y forcer.
  return <div style={{ background: "white", borderRadius: 12, padding: 20, boxShadow: "0 4px 18px rgba(31,56,100,0.08)", borderTop: "3px solid transparent", overflowWrap: "break-word", minWidth: 0, ...style }}>{children}</div>;
}
export function RuleBox({ children }) {
  return <div style={{ background: "#FBF3D9", border: "1px solid #EEDDA0", borderRadius: 10, padding: "12px 16px", marginBottom: 18, fontSize: 13, color: "#8a6d1a" }}><b>{"\u2139 "}</b>{children}</div>;
}
export function StatCard({ label, value, accent, icon: Icon }) {
  return (
    <Card style={{ borderTopColor: accent || "var(--accent)" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 11.5, fontWeight: 700, color: TEAL, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 8 }}>
        {Icon && <Icon size={14} />}{label}
      </div>
      <div style={{ fontFamily: "Poppins, sans-serif", fontWeight: 700, fontSize: 22, color: "var(--primary)" }}>{value}</div>
</Card>
  );
}
export function Field({ label, children }) {
  return <div style={{ marginBottom: 14 }}><label style={{ display: "block", fontWeight: 600, fontSize: 13, color: "var(--primary)", marginBottom: 5 }}>{label}</label>{children}</div>;
}
// "color" et "colorScheme" ajoutés (2026-09-29, suite Vie associative —
// zone d'écriture du fil d'actualité) : ce style ne fixait jamais la
// couleur du texte, seulement le fond (blanc). Le texte hérite alors de la
// couleur par défaut du navigateur pour un champ de saisie — sur un
// téléphone en mode sombre système, Chrome rend ce texte en blanc (le
// survol de :root { color-scheme: light dark } dans index.css l'y
// autorise), ce qui le rendait invisible sur ce fond blanc explicite :
// on tapait un message dans "Vie associative" sans jamais voir ce qu'on
// écrivait. Une couleur FIXE (pas une variable liée au thème sombre comme
// --text/--text-h, qui deviendrait elle-même presque blanche) et
// colorScheme: "light" forcent ce champ à rester lisible quel que soit le
// thème du téléphone — corrige tous les champs de l'application d'un
// coup, puisqu'ils partagent tous ce même style.
export const inputStyle = { width: "100%", padding: "9px 12px", borderRadius: 8, border: "1.5px solid #DCE0E8", fontSize: 14, fontFamily: "inherit", background: "white", color: "#242832", colorScheme: "light", boxSizing: "border-box" };

// Sous-ligne d'identité légale affichée sous le nom de l'association sur
// les reçus (2026-09-28, suite 80 — chantier « statut juridique / reçu
// personnalisable », voir internationalisation-universelle.md) : statut
// juridique, numéro d'enregistrement et adresse, chacun facultatif
// (Configuration → Informations légales et reçus). N'affiche rien du tout
// si aucun des trois n'est renseigné — aucun changement visible pour une
// association qui ne configure rien. Composant partagé pour rester
// identique entre le reçu de "Mon espace" (App.jsx) et le reçu de don
// (FinancesElargies.jsx).
export function OrgLegalSubline({ association }) {
  const parts = [association?.statut_juridique, association?.numero_enregistrement].filter(Boolean);
  if (!parts.length && !association?.adresse) return null;
  return (
    <div style={{ marginBottom: 10 }}>
      {parts.length > 0 && <p style={{ fontSize: 11.5, color: "#666", margin: "2px 0" }}>{parts.join(" — ")}</p>}
      {association?.adresse && <p style={{ fontSize: 11.5, color: "#666", margin: "2px 0", whiteSpace: "pre-wrap" }}>{association.adresse}</p>}
    </div>
  );
}

// Partage WhatsApp (2026-09-28, suite 81 — chantier « internationalisation »,
// voir internationalisation-universelle.md, point 4) : un simple lien
// `wa.me/?text=...` — gratuit, sans compte, sans API WhatsApp Business (celle-
// là est payante). Ouvre WhatsApp (application ou web) avec le texte déjà
// prérempli, laisse la personne choisir elle-même le contact ou le groupe à
// qui l'envoyer. WhatsApp étant le canal de communication dominant dans une
// grande partie de l'Afrique, de l'Amérique latine et de l'Asie du Sud,
// c'est le complément le plus utile au courriel pour les annonces et les
// événements.
export function whatsappShareUrl(text) {
  return `https://wa.me/?text=${encodeURIComponent(text)}`;
}
// Bouton prêt à l'emploi (pilule verte, icône + libellé) — utilisé pour les
// annonces. Les événements (Evenements.jsx) réutilisent plutôt
// `whatsappShareUrl()` directement, avec un bouton icône seule pour rester
// cohérent avec le bouton "ajouter au calendrier" déjà en place à côté.
export function WhatsAppShareButton({ text, label, style }) {
  return (
    <a
      href={whatsappShareUrl(text)} target="_blank" rel="noreferrer"
      style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 11.5, fontWeight: 600, color: "#1DA851", textDecoration: "none", border: "1px solid #25D366", borderRadius: 999, padding: "4px 10px", ...style }}
    >
      <MessageCircle size={13} /> {label}
    </a>
  );
}

// Notifications push web (2026-09-28, suite 82 — chantier
// « internationalisation », voir internationalisation-universelle.md,
// point 4 — deuxième moitié, après le bouton WhatsApp de la suite 81).
// Gratuit (Service Worker + Push API, standards du navigateur, aucun
// fournisseur tiers) — utile pour ne pas dépendre uniquement du quota
// gratuit de Resend pour joindre les membres. Voir sw.js (public/) et
// supabase/functions/send-push-notification pour le reste du mécanisme.
//
// Cette clé VAPID PUBLIQUE est faite pour être exposée côté client (comme
// une clé publique Stripe) : elle identifie ce serveur auprès du
// navigateur, elle ne signe jamais rien. La clé PRIVÉE correspondante
// vit uniquement comme secret de l'Edge Function send-push-notification
// (jamais dans ce code, jamais côté client).
export const VAPID_PUBLIC_KEY = "BMBp71MSNmcDyhb6ANUCTSv5TnvVyeR0C1DQRaZ_H6gWJ4qFRrUnAvGFGB6_5cCkMShzBAGWz5PdVNKwr89ZV-4";

function urlBase64ToUint8Array(base64String) {
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const rawData = atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; i++) outputArray[i] = rawData.charCodeAt(i);
  return outputArray;
}

// true si le navigateur sait au moins tenter des notifications push
// (absent sur certains navigateurs/contextes non sécurisés — le bouton
// 🔔 ne doit alors simplement pas s'afficher, plutôt que d'échouer).
export function pushSupported() {
  return typeof window !== "undefined" && "serviceWorker" in navigator && typeof window.PushManager !== "undefined";
}

// État courant, pour savoir quoi afficher dans le bouton 🔔 :
// "unsupported" | "denied" | "subscribed" | "unsubscribed".
export async function getPushSubscriptionState() {
  if (!pushSupported()) return "unsupported";
  if (typeof Notification !== "undefined" && Notification.permission === "denied") return "denied";
  try {
    const reg = await navigator.serviceWorker.getRegistration("/sw.js");
    const sub = reg ? await reg.pushManager.getSubscription() : null;
    return sub ? "subscribed" : "unsubscribed";
  } catch {
    return "unsubscribed";
  }
}

// Demande la permission, enregistre le Service Worker, s'abonne, puis
// enregistre l'abonnement dans push_subscriptions (upsert sur endpoint :
// un même appareil peut se réabonner sans créer de doublon). `supabase`
// est passé en paramètre plutôt qu'importé ici pour réutiliser le même
// client déjà authentifié que le reste de l'application.
export async function subscribeToPush(supabase, profileId, associationId) {
  if (!pushSupported()) throw new Error("unsupported");
  const permission = await Notification.requestPermission();
  if (permission !== "granted") throw new Error("denied");

  const reg = await navigator.serviceWorker.register("/sw.js");
  await navigator.serviceWorker.ready;

  let sub = await reg.pushManager.getSubscription();
  if (!sub) {
    sub = await reg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
    });
  }

  const json = sub.toJSON();
  const { error } = await supabase.from("push_subscriptions").upsert(
    {
      profile_id: profileId,
      association_id: associationId,
      endpoint: sub.endpoint,
      p256dh: json.keys.p256dh,
      auth: json.keys.auth,
    },
    { onConflict: "endpoint" }
  );
  if (error) throw error;
  return sub;
}

// Désabonne l'appareil courant et retire sa ligne de push_subscriptions.
export async function unsubscribeFromPush(supabase) {
  if (!pushSupported()) return;
  const reg = await navigator.serviceWorker.getRegistration("/sw.js");
  const sub = reg ? await reg.pushManager.getSubscription() : null;
  if (sub) {
    await supabase.from("push_subscriptions").delete().eq("endpoint", sub.endpoint);
    await sub.unsubscribe();
  }
}

// =====================================================================
// Mode hors-ligne / application installable (PWA) — suite 84, 2026-09-28,
// chantier « internationalisation » (voir
// claude/internationalisation-universelle.md, point « PWA/mode
// hors-ligne »). Portée volontairement limitée à « installable +
// résilient » (choix explicite de l'utilisateur, plutôt que de vraies
// données hors ligne avec synchronisation différée, un chantier
// nettement plus lourd) : l'application s'installe comme une vraie
// application, se recharge correctement même sans connexion (grâce au
// cache mis en place dans public/sw.js), et affiche un message clair
// plutôt qu'un échec silencieux quand une action a réellement besoin du
// serveur (donc de Supabase, jamais mis en cache par choix).
// =====================================================================

// Enregistre le Service Worker au démarrage de l'application (appelé une
// fois depuis main.jsx), INDÉPENDAMMENT des notifications push — la
// suite 82 ne l'enregistrait que lors d'un clic sur 🔔, ce qui aurait
// laissé sans cache/mode hors-ligne quiconque ne s'abonne jamais aux
// notifications. Enregistrement idempotent : si subscribeToPush()
// l'enregistre à nouveau plus tard avec la même URL, le navigateur
// réutilise simplement l'enregistrement déjà actif.
export function registerServiceWorker() {
  if (typeof navigator === "undefined" || !("serviceWorker" in navigator)) return;
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/sw.js").catch(() => { /* pas bloquant si ça échoue */ });
  });
}

// Bannière « hors connexion » : s'affiche automatiquement dès que le
// navigateur signale une perte de réseau (événements standards
// online/offline de `window`), pour que l'utilisateur comprenne tout de
// suite pourquoi une action échoue, plutôt que de découvrir un message
// d'erreur générique après coup. Se referme toute seule dès que la
// connexion revient. À placer une seule fois, tout en haut de
// l'application (avant même l'écran de connexion), pour couvrir tous les
// écrans sans dupliquer le composant.
export function OfflineBanner() {
  const { t } = useLang();
  const [online, setOnline] = useState(() => typeof navigator === "undefined" || navigator.onLine);
  useEffect(() => {
    function goOnline() { setOnline(true); }
    function goOffline() { setOnline(false); }
    window.addEventListener("online", goOnline);
    window.addEventListener("offline", goOffline);
    return () => {
      window.removeEventListener("online", goOnline);
      window.removeEventListener("offline", goOffline);
    };
  }, []);
  if (online) return null;
  return (
    <div style={{ position: "sticky", top: 0, zIndex: 2000, background: RED, color: "white", textAlign: "center", padding: "6px 12px", fontSize: 12.5, fontWeight: 600 }}>
      {t("offline_banner_msg")}
    </div>
  );
}

// Bloc de signature saisissable pour les documents imprimables/téléchargeables
// (procès-verbal d'élection, reçu de don, etc.) : le nom du signataire se
// tape dans un champ, puis "Valider" le fige en texte propre pour l'impression
// — combiné à la mention "signé électroniquement" affichée au-dessus par l'appelant.
// `printClass` doit correspondre à la classe "no-print" du document appelant
// (ex. "pv-no-print", "don-no-print") pour que les contrôles n'apparaissent pas à l'impression.
export function SignatureLine({ label, t, printClass = "" }) {
  const [name, setName] = useState("");
  const [validated, setValidated] = useState(false);
  const [focused, setFocused] = useState(false);
  return (
    <div style={{ minWidth: 240 }}>
      <div style={{ fontSize: 12, color: "#5B6270", marginBottom: 4 }}>{t("gov_pv_name_label")} :</div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 24, minHeight: 32 }}>
        {validated ? (
          <>
            <b style={{ fontSize: 13, color: "#222" }}>{name}</b>
            <button type="button" onClick={() => setValidated(false)} className={printClass} style={{ background: "none", border: "none", color: "var(--primary)", cursor: "pointer", fontSize: 11, textDecoration: "underline", padding: 0 }}>
              {t("action_edit")}
            </button>
          </>
        ) : (
          <>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              onFocus={() => setFocused(true)}
              onBlur={() => setFocused(false)}
              placeholder={t("don_receipt_sign_placeholder")}
              style={{
                border: "none", borderBottom: `1.5px solid ${focused ? "var(--primary)" : "#333"}`,
                outline: "none", fontSize: 13, padding: "6px 6px", background: focused ? "#F0F4F8" : "transparent",
                borderRadius: "3px 3px 0 0", flex: 1, minWidth: 140, fontFamily: "inherit", boxSizing: "border-box",
              }}
            />
            <button
              type="button" onClick={() => name.trim() && setValidated(true)} disabled={!name.trim()} className={printClass}
              style={{ fontSize: 10.5, padding: "4px 10px", borderRadius: 999, border: "1px solid var(--primary)", color: "var(--primary)", background: "none", cursor: name.trim() ? "pointer" : "not-allowed", opacity: name.trim() ? 1 : 0.5, flexShrink: 0 }}
            >
              {t("action_validate")}
            </button>
          </>
        )}
      </div>
      <div style={{ borderTop: "1px solid #333", paddingTop: 6, fontSize: 12, fontWeight: 600 }}>{label}</div>
    </div>
  );
}
export function Btn({ children, onClick, variant = "primary", disabled, type = "button", style }) {
  const base = { display: "inline-flex", alignItems: "center", gap: 8, padding: "10px 18px", borderRadius: 999, fontWeight: 600, fontSize: 14, cursor: disabled ? "not-allowed" : "pointer", border: "none", opacity: disabled ? 0.6 : 1 };
  const variants = {
    primary: { background: "var(--accent)", color: "var(--primary-dark)" },
    outline: { background: "transparent", color: "var(--primary)", border: "2px solid var(--primary)" },
    outlineWhite: { background: "transparent", color: "white", border: "2px solid rgba(255,255,255,.6)" },
    danger: { background: RED, color: "white" },
  };
  return <button type={type} onClick={disabled ? undefined : onClick} style={{ ...base, ...variants[variant], ...style }}>{children}</button>;
}
export function Table({ head, children, minWidth }) {
  // minWidth (optionnel) : force le défilement horizontal du wrapper
  // ci-dessus dès que le tableau comporte trop de colonnes pour tenir à
  // l'écran (ex. tableau des dons avec les colonnes France/Canada), au lieu
  // de laisser les colonnes se compresser jusqu'à devenir illisibles.
  return (
    <div className="table-scroll" style={{ overflowX: "auto", borderRadius: 12, boxShadow: "0 4px 18px rgba(31,56,100,0.08)" }}>
      <table style={{ width: "100%", minWidth, borderCollapse: "collapse", fontSize: 12.5 }}>
        <thead><tr>{head.map((h) => <th key={h} style={{ textAlign: "left", background: "var(--primary)", color: "white", padding: "7px 9px", fontSize: 10.5, textTransform: "uppercase", letterSpacing: ".03em" }}>{h}</th>)}</tr></thead>
        <tbody>{children}</tbody>
      </table>
    </div>
  );
}
export const td = { padding: "7px 9px", borderBottom: "1px solid #EEE" };
export function Banner({ children, tone = "info" }) {
  const tones = { info: [TEAL_LIGHT, TEAL], warn: ["#FBE4E1", RED] };
  const [bg, color] = tones[tone];
  return <div style={{ background: bg, color, padding: "8px 24px", fontSize: 12.5 }}>{children}</div>;
}

