// Langues affichées de droite à gauche (suite 83, 2026-09-28) — seule
// l'arabe pour l'instant. `dir` en dépend directement : c'est ce qui
// bascule automatiquement toute l'application en RTL (texte, alignement
// par défaut, et la plupart des mises en page flexbox qui n'imposent pas
// explicitement une direction gauche/droite) dès que la langue change,
// sans code supplémentaire à écrire ailleurs dans l'application pour ce
// cas général. Reste néanmoins une limite connue et documentée : les
// styles qui codent explicitement "left"/"right"/marginLeft/marginRight
// (propriétés physiques, pas logiques) ne s'inversent PAS automatiquement
// avec `dir` — un passage dédié module par module reste nécessaire pour
// les corriger au fil du temps, en plus de l'ajout des traductions.
const RTL_LANGS = ["ar"];

// Langues réellement proposées à l'utilisateur (suite 84, 2026-09-28) —
// l'arabe a été retiré du sélecteur (suite 83, mis en pause à la demande
// de l'utilisateur) mais le DICTIONARY.ar reste en place, dormant. Sans
// ce filtre, quelqu'un ayant déjà choisi l'arabe avant qu'il soit retiré
// resterait bloqué dessus indéfiniment : `localStorage` a gardé "ar" en
// mémoire, et rien ne le réinitialise tout seul. Toute valeur stockée qui
// n'est plus dans cette liste retombe automatiquement sur le français.
const AVAILABLE_LANGS = ["fr", "en"];

const LangContext = createContext({ lang: "fr", setLang: () => {}, t: (k) => k, dir: "ltr" });

export function LangProvider({ children }) {
  const [lang, setLang] = useState(() => {
    const stored = localStorage.getItem("app_lang");
    return AVAILABLE_LANGS.includes(stored) ? stored : "fr";
  });
  const dir = RTL_LANGS.includes(lang) ? "rtl" : "ltr";
  function changeLang(l) {
    setLang(l);
    try { localStorage.setItem("app_lang", l); } catch { /* stockage indisponible, ignorer */ }
  }
  // Applique la langue et la direction au document entier (<html lang=""
  // dir="">) — nécessaire pour que le navigateur applique réellement la
  // mise en page RTL (alignement du texte, ordre des colonnes flexbox par
  // défaut, etc.), pas seulement pour l'accessibilité/le SEO.
  useEffect(() => {
    try {
      document.documentElement.lang = lang;
      document.documentElement.dir = dir;
    } catch { /* environnement sans document (SSR/tests), ignorer */ }
  }, [lang, dir]);
  const t = (key) => DICTIONARY[lang]?.[key] || DICTIONARY.fr[key] || key;
  return <LangContext.Provider value={{ lang, setLang: changeLang, t, dir }}>{children}</LangContext.Provider>;
}
export function useLang() { return useContext(LangContext); }

export function LanguageSwitcher() {
  const { lang, setLang } = useLang();
  return (
    <select value={lang} onChange={(e) => setLang(e.target.value)} style={{
      background: "rgba(255,255,255,.1)", color: "white", border: "1px solid rgba(255,255,255,.3)",
      borderRadius: 6, fontSize: 11.5, padding: "3px 6px",
    }}>
      <option value="fr" style={{ color: "black" }}>FR</option>
      <option value="en" style={{ color: "black" }}>EN</option>
      {/* Option arabe retirée du sélecteur (suite 83, 2026-09-28) — à la
          demande de l'utilisateur, l'application reste FR/EN pour
          l'instant. L'infrastructure (bloc DICTIONARY.ar, bascule RTL
          dans LangProvider) reste en place, inactive : personne ne peut
          plus sélectionner l'arabe via l'interface, mais tout est prêt à
          être réactivé (juste remettre cette option) si le sujet revient
          plus tard. */}
    </select>
  );
}
// Taille de texte accessible (suite accessibilité, 2026-10-06) — même
// patron que LangProvider/useLang/LanguageSwitcher ci-dessus : un contexte,
// un stockage localStorage, un petit contrôle dans l'en-tête. La valeur
// choisie est appliquée en zoom CSS global sur <html> (voir index.css) —
// zoom et non font-size parce que la grande majorité des tailles de texte
// de l'application sont des fontSize en pixels fixés en ligne (pas des
// rem), qu'un simple changement de font-size sur <html> ne ferait pas
// bouger. Paliers fixes plutôt qu'un curseur libre : plus simple à piloter
// au clavier/lecteur d'écran, et évite les valeurs intermédiaires qui
// cassent des mises en page pensées pour des tailles entières.
const TEXT_SCALE_STEPS = [0.9, 1, 1.1, 1.2, 1.3];
const TEXT_SCALE_DEFAULT_INDEX = 1; // 1 => 100%, taille d'origine

const TextSizeContext = createContext({ scale: 1, stepIndex: TEXT_SCALE_DEFAULT_INDEX, increase: () => {}, decrease: () => {}, reset: () => {} });

export function TextSizeProvider({ children }) {
  const [stepIndex, setStepIndex] = useState(() => {
    try {
      const stored = Number(localStorage.getItem("app_text_scale_index"));
      return Number.isInteger(stored) && stored >= 0 && stored < TEXT_SCALE_STEPS.length ? stored : TEXT_SCALE_DEFAULT_INDEX;
    } catch { return TEXT_SCALE_DEFAULT_INDEX; }
  });
  const scale = TEXT_SCALE_STEPS[stepIndex];
  useEffect(() => {
    try {
      document.documentElement.style.setProperty("--app-text-scale", String(scale));
    } catch { /* environnement sans document (SSR/tests), ignorer */ }
  }, [scale]);
  function setIndex(i) {
    const clamped = Math.max(0, Math.min(TEXT_SCALE_STEPS.length - 1, i));
    setStepIndex(clamped);
    try { localStorage.setItem("app_text_scale_index", String(clamped)); } catch { /* stockage indisponible, ignorer */ }
  }
  const value = {
    scale,
    stepIndex,
    increase: () => setIndex(stepIndex + 1),
    decrease: () => setIndex(stepIndex - 1),
    reset: () => setIndex(TEXT_SCALE_DEFAULT_INDEX),
  };
  return <TextSizeContext.Provider value={value}>{children}</TextSizeContext.Provider>;
}
export function useTextSize() { return useContext(TextSizeContext); }

export function TextSizeControl() {
  const { scale, stepIndex, increase, decrease, reset } = useTextSize();
  const { t } = useLang();
  const btnStyle = (disabled) => ({
    background: "rgba(255,255,255,.1)", color: disabled ? "rgba(255,255,255,.35)" : "white",
    border: "1px solid rgba(255,255,255,.3)", borderRadius: 6, fontSize: 11.5, fontWeight: 700,
    width: 22, height: 22, display: "flex", alignItems: "center", justifyContent: "center",
    cursor: disabled ? "default" : "pointer", lineHeight: 1,
  });
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 3 }} title={t("text_size_tooltip")}>
      <button type="button" onClick={decrease} disabled={stepIndex === 0} aria-label={t("text_size_decrease")} style={btnStyle(stepIndex === 0)}>A-</button>
      <button
        type="button"
        onClick={reset}
        aria-label={t("text_size_reset")}
        style={{ background: "none", border: "none", color: "rgba(255,255,255,.75)", fontSize: 10.5, width: 32, textAlign: "center", cursor: "pointer", fontVariantNumeric: "tabular-nums" }}
      >
        {Math.round(scale * 100)}%
      </button>
      <button type="button" onClick={increase} disabled={stepIndex === TEXT_SCALE_STEPS.length - 1} aria-label={t("text_size_increase")} style={btnStyle(stepIndex === TEXT_SCALE_STEPS.length - 1)}>A+</button>
    </div>
  );
}

// Badge rond de notifications non lues (suite 92) — mêmes valeurs
// (couleur, taille, rayon) que les badges déjà en place sur "Demandes de
// suppression" / "Gestion des accès" / "Paiements Interac" dans le menu
// de App.jsx, pour un rendu visuellement identique partout.
export function NotifBadge({ count }) {
  if (!count) return null;
  return (
    <span style={{
      background: "#C0392B", color: "white", borderRadius: 999, fontSize: 9.5, fontWeight: 700,
      minWidth: 14, height: 14, display: "inline-flex", alignItems: "center", justifyContent: "center", padding: "0 3px",
    }}>
      {count > 99 ? "99+" : count}
    </span>
  );
}
